import{_ as t,o as a,c as o,ae as s}from"./chunks/framework.YL6nI5ZP.js";const u=JSON.parse('{"title":"How to Run the App Locally","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/01-run-locally.md","filePath":"how-to/01-run-locally.md"}'),r={name:"how-to/01-run-locally.md"};function n(i,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="how-to-run-the-app-locally" tabindex="-1">How to Run the App Locally <a class="header-anchor" href="#how-to-run-the-app-locally" aria-label="Permalink to &quot;How to Run the App Locally&quot;">​</a></h1><p>Run the Local SWMM web app on your own computer with the bundled Python static server, instead of the production site.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Python 3 and a modern browser. (Node is only needed for <code>npm install</code> and the tooling scripts.)</li></ul><h2 id="_1-clone-the-repository" tabindex="-1">1. Clone the repository <a class="header-anchor" href="#_1-clone-the-repository" aria-label="Permalink to &quot;1. Clone the repository&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experimental</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/JoaquinAlvarado-py/LocalSWMM.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LocalSWMM</span></span></code></pre></div><h2 id="_2-start-the-local-web-server" tabindex="-1">2. Start the local web server <a class="header-anchor" href="#_2-start-the-local-web-server" aria-label="Permalink to &quot;2. Start the local web server&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # serves ./public on http://127.0.0.1:8080</span></span></code></pre></div><h2 id="_3-open-the-app" tabindex="-1">3. Open the app <a class="header-anchor" href="#_3-open-the-app" aria-label="Permalink to &quot;3. Open the app&quot;">​</a></h2><p>Open <strong><a href="http://127.0.0.1:8080" target="_blank" rel="noreferrer">http://127.0.0.1:8080</a></strong> in your web browser. If the basemap doesn&#39;t load, you need to add your Mapbox token to <code>public/config.js</code> — see <a href="./02-configure">How to Configure Local SWMM</a>.</p><h2 id="_4-optional-install-the-js-tooling" tabindex="-1">4. (Optional) Install the JS tooling <a class="header-anchor" href="#_4-optional-install-the-js-tooling" aria-label="Permalink to &quot;4. (Optional) Install the JS tooling&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # installs triangle-wasm (dev dependency, vendored copy)</span></span></code></pre></div><h2 id="_5-verify-with-a-sample-model" tabindex="-1">5. Verify with a sample model <a class="header-anchor" href="#_5-verify-with-a-sample-model" aria-label="Permalink to &quot;5. Verify with a sample model&quot;">​</a></h2><p>Load <strong>Bellinge Web</strong> from the <strong>Open Model ▾</strong> dropdown, then press <strong>Run</strong>. This is the reference network used throughout the test suite.</p><h2 id="what-the-server-does" tabindex="-1">What the server does <a class="header-anchor" href="#what-the-server-does" aria-label="Permalink to &quot;What the server does&quot;">​</a></h2><p><code>server.py</code> is a zero-dependency static server (Python stdlib):</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Value</th></tr></thead><tbody><tr><td>Bind</td><td><code>127.0.0.1</code> only</td></tr><tr><td>Port</td><td><strong>8080</strong></td></tr><tr><td>Document root</td><td><code>&lt;repo&gt;/public</code></td></tr><tr><td>Endpoints</td><td><code>GET /api/status</code> → <code>{&quot;status&quot;:&quot;running&quot;,&quot;msg&quot;:&quot;3D Map Prototype Server Online&quot;}</code>; everything else = static GET</td></tr><tr><td>Headers</td><td><code>Cache-Control: no-store</code> (fresh wasm/JS every reload)</td></tr><tr><td>CORS</td><td><code>Access-Control-Allow-Origin: *</code> on OPTIONS + <code>/api/status</code></td></tr><tr><td>Concurrency</td><td><code>ThreadingTCPServer</code>, <code>daemon_threads=True</code></td></tr></tbody></table><p>The server sends the same <code>Cross-Origin-Opener-Policy: same-origin</code> / <code>Cross-Origin-Embedder-Policy: credentialless</code> headers as production, so the threaded engine (pthreads/<code>SharedArrayBuffer</code>) works on <code>http://127.0.0.1:8080</code> out of the box.</p><h2 id="known-discrepancy" tabindex="-1">Known discrepancy <a class="header-anchor" href="#known-discrepancy" aria-label="Permalink to &quot;Known discrepancy&quot;">​</a></h2><blockquote><p>The README says the project directory is <code>SWMM_3D_Web_UI</code> and the URL is <code>http://localhost:8000</code>. The actual directory is <code>LocalSWMM</code> and the server listens on port <strong>8080</strong> (<code>server.py:6</code>). Use the commands above.</p></blockquote>`,20)])])}const b=t(r,[["render",n]]);export{u as __pageData,b as default};
